detail.example:
# 데이터 직렬화(Avro/Parquet/ORC) 예시: Python 3에서 실행 가능한 코드
formats = {"stream": "Avro", "analytics": "Parquet"}
print(formats["analytics"])

# 컬럼 기반 포맷(Parquet) 예시: Python 3에서 실행 가능한 코드
columns = {"age": [20, 30], "city": ["A", "B"]}
print(sum(columns["age"]) / len(columns["age"]))

# 압축 코덱(Snappy/Zstd) 예시: Python 3에서 실행 가능한 코드
codec = {"name": "zstd", "ratio": 0.35}
print(codec["ratio"] < 0.5)

# ACID on 데이터 레이크 예시: Python 3에서 실행 가능한 코드
transaction = {"write": True, "commit": True}
print(transaction["write"] and transaction["commit"])

# 타임 트래블(Time Travel) 예시: Python 3에서 실행 가능한 코드
versions = {1: "old", 2: "current"}
print(versions[1])

# 스키마 진화(데이터 레이크) 예시: Python 3에서 실행 가능한 코드
old = {"id": 1}
new = {**old, "email": None}
print(new)

# 데이터 스큐(Data Skew) 예시: Python 3에서 실행 가능한 코드
counts = {"A": 1000, "B": 10, "C": 12}
print(max(counts.values()) / min(counts.values()))

# 셔플 최적화 예시: Python 3에서 실행 가능한 코드
records = [("A", 1), ("A", 2), ("B", 3)]
preagg = {}
for k, v in records:
    preagg[k] = preagg.get(k, 0) + v
print(preagg)

# 데이터 계약(Data Contract) 예시: Python 3에서 실행 가능한 코드
contract = {"fields": ["id", "amount"], "owner": "orders"}
print("amount" in contract["fields"])

# Debezium 예시: Python 3에서 실행 가능한 코드
event = {"source": "mysql", "op": "c"}
print(event["source"], event["op"])

# 데이터 메시(Data Mesh) 예시: Python 3에서 실행 가능한 코드
domains = {"sales": "owner-a", "support": "owner-b"}
print(domains["sales"])

# 도메인 소유 데이터 예시: Python 3에서 실행 가능한 코드
owners = {"invoice": "finance", "ticket": "support"}
print(owners["invoice"])

# 셀프 서비스 플랫폼 예시: Python 3에서 실행 가능한 코드
platform = {"create_pipeline": True, "request_access": True}
print(all(platform.values()))

# 데이터 오너십 예시: Python 3에서 실행 가능한 코드
dataset = {"name": "orders", "owner": "commerce-team"}
print(dataset["owner"])

# 데이터 제품 예시: Python 3에서 실행 가능한 코드
product = {"name": "daily-sales", "sla": "09:00"}
print(product["sla"])

# 상태 저장 스트림 처리 예시: Python 3에서 실행 가능한 코드
state = {}
for user in ["u1", "u1", "u2"]:
    state[user] = state.get(user, 0) + 1
print(state)

# 상태 백엔드 예시: Python 3에서 실행 가능한 코드
backend = {"type": "rocksdb", "durable": True}
print(backend["durable"])

# 체크포인트(Flink) 예시: Python 3에서 실행 가능한 코드
checkpoint = {"offset": 120, "state": {"count": 9}}
print(checkpoint["offset"])

# 실시간 대시보드 아키텍처 예시: Python 3에서 실행 가능한 코드
metrics = {"orders_per_min": 42}
print(metrics["orders_per_min"])

# Source Connector 예시: Python 3에서 실행 가능한 코드
source = {"from": "postgres", "to": "topic.orders"}
print(source["to"])

# Sink Connector 예시: Python 3에서 실행 가능한 코드
sink = {"from": "topic.orders", "to": "s3"}
print(sink["to"])

# 스키마 레지스트리(Confluent) 예시: Python 3에서 실행 가능한 코드
schemas = {"Order": [1, 2]}
print(max(schemas["Order"]))

# 컴팩션 정책(Log Compaction) 예시: Python 3에서 실행 가능한 코드
events = [("u1", "old"), ("u1", "new")]
latest = {}
for k, v in events:
    latest[k] = v
print(latest)

# 스트림-스트림 조인 예시: Python 3에서 실행 가능한 코드
clicks = {"u1": 10}
purchases = {"u1": 12}
print(purchases["u1"] - clicks["u1"] <= 5)

# 데이터 오케스트레이션(Airflow) 예시: Python 3에서 실행 가능한 코드
tasks = {"extract": [], "load": ["extract"]}
print(tasks["load"])

# DAG(워크플로 정의) 예시: Python 3에서 실행 가능한 코드
dag = {"transform": ["extract"], "load": ["transform"]}
print(dag["load"])
